+        assert.ok(builder.indexOf('pack_require_gate.cjs') !== -1,
+            'ci/release_packs.mjs must import ci/pack_require_gate.cjs — the ' +
+            'release self-test asserting every packed require resolves inside ' +
+            'the zip (gh-812 AC1/AC3)');
+    });
