+        assert.ok(builder.indexOf('::warning::') !== -1 &&
+            /shipped/i.test(builder),
+            'a gh outage must fall back to the ledger (today\'s behavior), ' +
+            'not fail releases on infrastructure the gate cannot control');
+    });
+});
