'use strict';
/**
 * Pack-release require sanity gate (gh-812, live incident 2026-10-09).
 *
 * The release self-test demanded by gh-812 AC1/AC3: after a pack zip is
 * built, every literal relative `require('./x')` / `require('../y')` in
 * every packed .js must resolve to a file INSIDE the zip — a pack whose
 * code requires a module the zip does not carry must FAIL the release
 * (exit != 0) before the ledger commit and the publish, not live on the
 * fa runners ("Failed to require module: ./reviewVerdicts.js").
 *
 * validatePack() cannot catch this class: it re-hashes manifest entries
 * against themselves, which proves the zip matches its manifest, never
 * that the payload is self-consistent.
 *
 * Pure classification — no fs, no zip, no exec: the caller (ci/release_packs.mjs)
 * extracts the zip and hands over {path, source} records; this CommonJS twin
 * of the builder keeps the decisions unit-testable in the dmtools runner
 * (same split as ci/pack_release_guard.cjs).
 *
 * Known limit (documented, gh-812 test plan): dynamically assembled requires
 * (`require(prefix + name + '.js')`) cannot be resolved statically and are
 * ignored. The require that broke the incident was a string literal, and
 * every require in this repo's packed code is. Comment/JSdoc text is NOT
 * stripped — the runtime resolver union (see resolveRequireCandidates) kept
 * every doc example in this repo resolvable, and stripping risks missing a
 * real require swallowed by a misdetected regex literal.
 */

/** Literal relative require: require('./a.js'), require ("../b/c.js"). */
var REQUIRE_RE = /\brequire\s*\(\s*(['"])((?:\.\.?\/)[^'"]*)\1\s*\)/g;

/**
 * String-literal relative require specs in [source], in order.
 * Bare ids ('dmtools') and dynamic requires are out of scope — see header.
 */
function requireSpecs(source) {
    var specs = [];
    // Fresh stateful copy per call: a shared /g regex carries lastIndex
    // across calls (and resetting it mid-loop would rematch forever).
    var re = new RegExp(REQUIRE_RE.source, 'g');
    var m = re.exec(source);
    while (m !== null) {
        specs.push(m[2]);
        m = re.exec(source);
    }
    return specs;
}

/**
 * Zip-layout path for [spec] required from [fromPath], resolved against the
 * requiring file's directory ('.'/'..'/empty segments normalized away).
 */
function resolveRequire(fromPath, spec) {
    var parts = fromPath.split('/');
    parts.pop(); // the requiring file's directory
    return normalizePath(parts.concat(spec.split('/')));
}

/** Zip-layout path from [parts], '.'/'..'/empty segments normalized away. */
function normalizePath(parts) {
    var out = [];
    for (var i = 0; i < parts.length; i++) {
        var seg = parts[i];
        if (seg === '' || seg === '.') continue;
        if (seg === '..') out.pop();
        else out.push(seg);
    }
    return out.join('/');
}

/**
 * ALL zip paths [spec] may resolve to at runtime. dmtools' loader resolves
 * literal relative requires against BOTH the requiring file's directory
 * (Node-style siblings — js/common/commentMarkup.js requiring
 * './ticketKeyShapes.js') AND the pack's js/ module root (sources eval'd by
 * the worker engines are authored as if from js/ — githubSource.js worker
 * strings requiring './common/smProvider.js'; the gh-812 incident error
 * itself printed <pack>/js/reviewVerdicts.js for a spec required from
 * js/common/). A require is RESOLVED when any base finds the file, and
 * UNRESOLVED only when neither can — exactly the gh-812 class of packed
 * code requiring a file the zip does not carry.
 */
function resolveRequireCandidates(fromPath, spec) {
    var candidates = [resolveRequire(fromPath, spec)];
    if (spec.indexOf('./') === 0) {
        candidates.push(normalizePath(['js'].concat(spec.slice(2).split('/'))));
    }
    return candidates;
}

/**
 * Membership test across both container shapes the gate accepts: a plain
 * object map (path → true) or a Set. A live red-team run caught the naive
 * `paths[target]` read silently failing on a Set — every require read as
 * unresolved.
 */
function pathSetHas(paths, key) {
    if (paths && typeof paths.has === 'function') return paths.has(key);
    return !!(paths && paths[key]);
}

/**
 * Requires in [files] ({path, source}) that resolve to no path in
 * [knownPaths] (defaults to the files' own paths; plain object map or Set).
 * Returns [{from, spec, target, bases}] — empty means the pack is
 * self-consistent. [target] is the file-relative resolution (primary);
 * [bases] lists every zip path that was tried.
 */
function unresolvedRequires(files, knownPaths) {
    var paths = knownPaths;
    var i;
    if (!paths) {
        paths = {};
        for (i = 0; i < files.length; i++) paths[files[i].path] = true;
    }
    var unresolved = [];
    for (i = 0; i < files.length; i++) {
        var specs = requireSpecs(files[i].source || '');
        for (var s = 0; s < specs.length; s++) {
            var bases = resolveRequireCandidates(files[i].path, specs[s]);
            var resolved = false;
            for (var b = 0; b < bases.length; b++) {
                if (pathSetHas(paths, bases[b]) || pathSetHas(paths, bases[b] + '.js')) {
                    resolved = true;
                    break;
                }
            }
            if (!resolved) {
                unresolved.push({
                    from: files[i].path,
                    spec: specs[s],
                    target: bases[0],
                    bases: bases,
                });
            }
        }
    }
    return unresolved;
}

module.exports = {
    requireSpecs: requireSpecs,
    resolveRequire: resolveRequire,
    resolveRequireCandidates: resolveRequireCandidates,
    unresolvedRequires: unresolvedRequires,
};

'use strict';
/**
 * Pack-release version guard (gh-812, live incident 2026-10-09).
 *
 * Encodes the gh-812 version contract: two releases with differing pack
 * content NEVER share a version string (AC2).
 *
 * What broke: ci/release_packs.mjs derived pack versions from versions.json
 * on main — a LEDGER whose push back to main is best-effort (a rejected
 * direct push only warns). The ledger never landed, so every release
 * recomputed the same bump from the same stale base: eight consecutive
 * releases (20261008-095538 → 20261009-091304) all advertised
 * sm_github: 0.1.36 while the content changed underneath, and 091304
 * republished a DIFFERENT sm_github-0.1.36.zip than 075526 had shipped.
 * Version-keyed consumer caches then ran mixed content — every fa
 * machine-sm tick red for ~25 min.
 *
 * Decisions (each mirrors the append-only source of truth it trusts):
 *   V1 the SHIPPED version beats the ledger — a release tag, once cut,
 *      cannot be rewritten by a failed push; versions.json can (and did).
 *   V2 an affected agent bumps from the shipped base — never re-ships a
 *      version that is already out there.
 *   V3 a rebuilt-but-unbumped agent whose payload differs from what its
 *      unchanged version already shipped gets an extra patch bump.
 *   V4 the payload fingerprint covers file paths + sha256 only — manifest
 *      metadata (version, sourceCommit) changes on every rebuild and must
 *      not force a bump by itself.
 *
 * Pure classification — no fs, no network: the caller (ci/release_packs.mjs)
 * downloads the previous release's catalog.json + same-version pack zips and
 * hands over manifest.json text. CommonJS twin of the builder, unit-testable
 * in the dmtools runner (same split as ci/pack_release_guard.cjs).
 */

/** Semver bump: 'patch' | 'minor' | 'major'. */
function bump(version, kind) {
    var parts = String(version).split('.');
    var maj = parseInt(parts[0], 10) || 0;
    var min = parseInt(parts[1], 10) || 0;
    var pat = parseInt(parts[2], 10) || 0;
    if (kind === 'major') return (maj + 1) + '.0.0';
    if (kind === 'minor') return maj + '.' + (min + 1) + '.0';
    return maj + '.' + min + '.' + (pat + 1);
}

/**
 * V1: base version for a release — what the previous release SHIPPED for
 * the agent, falling back to the ledger, falling back to 0.1.0.
 */
function resolveBaseVersion(ledgerVersion, shippedVersion) {
    if (shippedVersion) return shippedVersion;
    if (ledgerVersion) return ledgerVersion;
    return '0.1.0';
}

/** V2: version to build at — affected agents bump the base, others keep it. */
function resolveCandidateVersion(baseVersion, bumpKind, affected) {
    return affected ? bump(baseVersion, bumpKind) : baseVersion;
}

/**
 * V3: final version to ship — when the freshly built payload differs from
 * what [candidateVersion] already shipped, re-version one patch up.
 * [differsFromShipped] comes from fingerprintsDiffer(); false covers both
 * "identical payload" and "no previous artifact to compare against".
 */
function resolveShipVersion(candidateVersion, differsFromShipped) {
    return differsFromShipped ? bump(candidateVersion, 'patch') : candidateVersion;
}

/**
 * V4: stable fingerprint of a pack's PAYLOAD from its manifest.json text —
 * sorted path:sha256 pairs. Manifest metadata (agent, version, sourceCommit)
 * is deliberately excluded: it changes on every rebuild and every commit and
 * must never read as a content change. Unparseable/absent input → null
 * (the caller treats null as "cannot compare").
 */
function payloadFingerprint(manifestJson) {
    if (!manifestJson) return null;
    var manifest;
    try {
        manifest = JSON.parse(manifestJson);
    } catch (e) {
        return null;
    }
    var files = manifest.files || [];
    var entries = [];
    for (var i = 0; i < files.length; i++) {
        entries.push(files[i].path + ':' + files[i].sha256);
    }
    entries.sort();
    return entries.join('\n');
}

/**
 * True when two manifests describe DIFFERENT payloads. Missing/unparseable
 * input on either side → false: no previous artifact to compare against must
 * never force a bump from nothing.
 */
function fingerprintsDiffer(prevManifestJson, nextManifestJson) {
    var prev = payloadFingerprint(prevManifestJson);
    var next = payloadFingerprint(nextManifestJson);
    if (prev === null || next === null) return false;
    return prev !== next;
}

module.exports = {
    bump: bump,
    resolveBaseVersion: resolveBaseVersion,
    resolveCandidateVersion: resolveCandidateVersion,
    resolveShipVersion: resolveShipVersion,
    payloadFingerprint: payloadFingerprint,
    fingerprintsDiffer: fingerprintsDiffer,
};

