#!/usr/bin/env node
/**
 * Agent pack release builder (dmtools-agents#441).
 *
 * Computes the affected agent set from the git diff since the last release,
 * bumps each affected agent's version in versions.json, builds EVERY agent
 * pack with `dmtools compile` (the single implementation of the pack format —
 * dm.ai#595), validates each zip against its manifest, and writes a FULL
 * catalog.json (every agent -> its current version): each release is a
 * self-contained snapshot because the registry resolver resolves
 * `<agent>@latest` against the newest release's catalog only.
 *
 * Usage:
 *   node ci/release_packs.mjs [--agents=all|name1,name2] [--bump=patch|minor|major]
 *       [--base-ref <git-ref>] [--prev-release-tag <tag>] [--out dist] [--dry-run]
 *
 * Exit 0 with an empty affected set means "nothing to release" (not an error).
 *
 * gh-812 release integrity (live incident 2026-10-09): the builder derives
 * every version from the PREVIOUS RELEASE's shipped catalog (append-only,
 * cannot be rewritten by a failed ledger push) rather than versions.json on
 * main (--prev-release-tag, best-effort), re-version an unbumped agent whose
 * rebuilt payload differs from what its unchanged version already shipped
 * (never republish changed content under a shipped version), and gate every
 * built zip through the require sanity check (assertZipRequires) BEFORE the
 * ledger commit and the publish — a pack whose code requires a file the zip
 * does not carry must fail the release, not the fa runners.
 */
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import {
  readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync,
  copyFileSync, cpSync, chmodSync, mkdtempSync, rmSync, statSync, utimesSync,
} from 'node:fs';
import { basename, dirname, join, resolve, sep } from 'node:path';
import { tmpdir } from 'node:os';
import { execSync } from 'node:child_process';

// Pack launch-surface contract (Wave 2, owner 2026-10-01): teammate packs
// carry launch.json (+ loop/verdict.sh for review packs) inside the zip.
import { launchExtras, mergeManifest } from './pack_launch_contract.cjs';

// Release-guard classification (gh-690): versions.json is the version
// LEDGER — data, not an agent. The old inline filter in allAgents() swept it
// in as a phantom "versions" agent (a bogus ledger key plus a phantom
// versions-<v>.zip in every release). pack_release_guard.cjs is the single
// definition of "what is an agent" — the affected-set path uses it too.
import {
  agentNamesFromFiles, isAgentConfigFile, toAgentName,
} from './pack_release_guard.cjs';

// gh-812: version uniqueness (shipped-version-first resolution, payload
// fingerprints) + the require sanity gate — both pure CommonJS twins kept
// unit-testable in the dmtools runner (same split as pack_release_guard.cjs).
import {
  bump, resolveBaseVersion, resolveCandidateVersion, resolveShipVersion,
  fingerprintsDiffer,
} from './pack_version_guard.cjs';
import { unresolvedRequires } from './pack_require_gate.cjs';

const ROOT = process.cwd();
const VERSIONS_FILE = join(ROOT, 'versions.json');
const OUT_DIR = arg('--out') || 'dist';
const BUMP = arg('--bump') || 'patch';
const AGENTS_INPUT = arg('--agents') || '';
const BASE_REF = arg('--base-ref') || '';
const PREV_TAG = arg('--prev-release-tag') || '';
const DRY_RUN = hasFlag('--dry-run');

/** Directory prefixes whose change affects every agent (shared runtime code). */
const SHARED_PREFIXES = ['js/', 'instructions/', 'prompts/', 'scripts/'];

/**
 * The factory-setup asset (owner mandate 2026-10-03: "no factory-agents tree
 * checkout in the factory") — the workflow glue the factory needs at run
 * time, shipped as a release zip so awf's factory-teammate.yml never clones
 * the dmtools-agents tree:
 *   setup/    — the whole toolbelt (install.sh, cache.sh, review-verdict.sh,
 *               fa-session.sh, per-tool installers, _common.sh)
 *   scripts/git-push-guard.sh — the guard fallback (kit stays primary)
 *   configs/  — the four leg entry configs the guard job names as its
 *               parent-config fallback (pack launch.json stays primary)
 */
const FACTORY_SETUP_LEGS = ['bug_development', 'story_development', 'pr_review', 'pr_rework'];

/** True when any changed file lives under setup/ or the builder itself. */
function setupTouched() {
  if (AGENTS_INPUT) return true; // explicit dispatch: always ship a fresh asset
  const changed = changedFiles();
  if (changed === null) return true;
  // setup/ content or THIS builder — either way the factory-setup asset
  // must re-ship (live: the builder-only diff cut no release and the
  // factory-setup asset never landed, 2026-10-03).
  return changed.some((f) => f.startsWith('setup/') || f === 'ci/release_packs.mjs');
}

/** Builds dist/factory-setup-<datestamp>.zip + .sha256 sidecar. */
function buildFactorySetup() {
  const stamp = new Date().toISOString().replace(/[-:T.]/g, '').slice(0, 14); // YYYYMMDDHHMMSS
  mkdirSync(OUT_DIR, { recursive: true });
  const zipPath = resolve(OUT_DIR, `factory-setup-${stamp}.zip`);
  const staging = mkdtempSync(join(tmpdir(), 'factory-setup-'));
  try {
    mkdirSync(join(staging, 'configs'), { recursive: true });
    cpSync(join(ROOT, 'setup'), join(staging, 'setup'), { recursive: true });
    mkdirSync(join(staging, 'scripts'), { recursive: true });
    copyFileSync(join(ROOT, 'scripts', 'git-push-guard.sh'), join(staging, 'scripts', 'git-push-guard.sh'));
    for (const leg of FACTORY_SETUP_LEGS) {
      copyFileSync(join(ROOT, `${leg}.json`), join(staging, 'configs', `${leg}.json`));
    }
    // Plain integrity inventory (not a dmtools agent-pack manifest — this is
    // workflow glue, never resolved by the agent pack registry).
    const sums = [];
    const walk = (dir, rel) => {
      for (const e of readdirSync(dir, { withFileTypes: true })) {
        const relPath = rel ? `${rel}/${e.name}` : e.name;
        if (e.isDirectory()) walk(join(dir, e.name), relPath);
        else sums.push(`${createHash('sha256').update(readFileSync(join(dir, e.name))).digest('hex')}  ${relPath}`);
      }
    };
    walk(staging, '');
    writeFileSync(join(staging, 'SHA256SUMS'), `${sums.sort().join('\n')}\n`);
    execSync(`cd ${JSON.stringify(staging)} && zip -q -r ${JSON.stringify(zipPath)} .`);
    const digest = createHash('sha256').update(readFileSync(zipPath)).digest('hex');
    writeFileSync(`${zipPath}.sha256`, `${digest}  ${basename(zipPath)}\n`);
    console.log(`built ${basename(zipPath)} (${sums.length} files)`);
  } finally {
    rmSync(staging, { recursive: true, force: true });
  }
  return zipPath;
}

function arg(name) {
  // Support both "--flag value" and "--flag=value".
  const eq = process.argv.find((a) => a.startsWith(`${name}=`));
  if (eq) return eq.slice(name.length + 1);
  const i = process.argv.indexOf(name);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : null;
}

function hasFlag(name) {
  return process.argv.includes(name);
}

function readVersions() {
  return JSON.parse(readFileSync(VERSIONS_FILE, 'utf8'));
}

/** All root-level *.json entry points (agent names), excluding package*.json
 *  and the versions.json ledger (gh-690 — see ci/pack_release_guard.cjs). */
function allAgents() {
  return agentNamesFromFiles(readdirSync(ROOT));
}

/** Files changed since the base ref (last release tag), or all when none. */
function changedFiles() {
  if (!BASE_REF) return null; // caller treats null as "unknown -> all agents"
  try {
    const out = execSync(`git diff --name-only ${BASE_REF}...HEAD`, { cwd: ROOT, encoding: 'utf8' });
    return out.split('\n').map((s) => s.trim()).filter(Boolean);
  } catch (e) {
    console.warn(`git diff against ${BASE_REF} failed (${e.message}); releasing all agents`);
    return null;
  }
}

/**
 * Affected set: changed root entry configs, plus every agent when any shared
 * runtime file changed (conservative superset of the closure intersection —
 * never misses an affected agent).
 */
function computeAffectedSet() {
  if (AGENTS_INPUT === 'all') return allAgents();
  if (AGENTS_INPUT) return AGENTS_INPUT.split(',').map(…

/**
 * Unit tests: the pack-release require sanity gate (gh-812).
 *
 * Guards the gh-812 incident class (live 2026-10-09 09:36-09:52Z): a pack
 * whose code requires a module the zip does not carry sailed through
 * validatePack() (which only re-hashes manifest entries against themselves)
 * and shipped; version-keyed consumer caches then ran the requiring code
 * against an installed tree without the file — every fa machine-sm tick
 * failed with "Failed to require module: ./reviewVerdicts.js".
 *
 * The gate (ci/pack_require_gate.cjs) is the release self-test demanded by
 * gh-812 AC1/AC3: after build, every literal relative require in every
 * packed .js must resolve to a file inside the zip, or the release fails
 * (exit != 0) BEFORE the ledger commit and publish.
 *
 * L2 red-team fixture ("replay the 091304 content set"): the mixed state the
 * fa runners actually executed — post-gh-807 requiring code over an installed
 * tree without js/common/reviewVerdicts.js. The gate MUST report it.
 *
 * Uses: loadModule(), suite(), test(), assert
 */

'use strict';

/* global loadModule, assert, test, suite */

function gate() {
    return loadModule('ci/pack_require_gate.cjs');
}

// ── require spec extraction ──────────────────────────────────────────────────

suite('require gate: literal relative require extraction', function () {

    test('a top-level literal require is found', function () {
        var specs = gate().requireSpecs("var x = require('./common/reviewVerdicts.js');");
        assert.deepEqual(specs, ['./common/reviewVerdicts.js']);
    });

    test('a lazy require nested in a function body is found (smProvider.js:151 shape)', function () {
        // gh-812: the require that broke the fa ticks is NOT top-level — it
        // sits inside a method body. A walker that only scans the module
        // top level misses it; the gate must not.
        var source = [
            'var mod = null;',
            'function getVerdicts() {',
            '    if (!mod) {',
            "        mod = require('./reviewVerdicts.js');",
            '    }',
            '    return mod;',
            '}',
        ].join('\n');
        assert.deepEqual(gate().requireSpecs(source), ['./reviewVerdicts.js']);
    });

    test('double-quoted requires are found', function () {
        var specs = gate().requireSpecs('var x = require("../common/scm.js");');
        assert.deepEqual(specs, ['../common/scm.js']);
    });

    test('whitespace inside the call does not hide the spec', function () {
        var specs = gate().requireSpecs("var x = require( './a.js' );");
        assert.deepEqual(specs, ['./a.js']);
    });

    test('multiple requires in one source are all found, in order', function () {
        var source = [
            "var a = require('./common/scm.js');",
            "var b = require('./configLoader.js');",
        ].join('\n');
        assert.deepEqual(gate().requireSpecs(source),
            ['./common/scm.js', './configLoader.js']);
    });

    test('bare module ids are ignored (not relative, not resolvable in the zip)', function () {
        assert.deepEqual(gate().requireSpecs("var x = require('dmtools');"), []);
    });

    test('dynamic (non-literal) requires are ignored — documented static-gate limit', function () {
        assert.deepEqual(gate().requireSpecs('var x = require(prefix + name + ".js");'), []);
    });

    test('a source with no requires yields an empty list', function () {
        assert.deepEqual(gate().requireSpecs('var x = 1;'), []);
    });
});

// ── resolution against the zip file set ──────────────────────────────────────

suite('require gate: relative resolution against the zip layout', function () {

    test('./ resolves inside the requiring file directory', function () {
        assert.equal(
            gate().resolveRequire('js/common/smProvider.js', './reviewVerdicts.js'),
            'js/common/reviewVerdicts.js');
    });

    test('../ climbs one directory', function () {
        assert.equal(
            gate().resolveRequire('js/common/smProvider.js', '../configLoader.js'),
            'js/configLoader.js');
    });

    test('the result is zip-layout normalized (no ./ segments, no leading slash)', function () {
        assert.equal(
            gate().resolveRequire('js/smAgent.js', '././common//reviewVerdicts.js'),
            'js/common/reviewVerdicts.js');
    });

    test('union resolution: the js/ module root is a second base (worker-source shape)', function () {
        // githubSource.js embeds worker sources authored as if from js/:
        // require('./common/smProvider.js') from js/sm/sources/ resolves via
        // the js/ ROOT, not the requiring file's directory.
        var bases = gate().resolveRequireCandidates('js/sm/sources/githubSource.js', './common/smProvider.js');
        assert.deepEqual(bases, ['js/sm/sources/common/smProvider.js', 'js/common/smProvider.js']);
    });

    test('a ../ spec has only the file-relative base (climbing out of js/ is meaningless in a pack)', function () {
        var bases = gate().resolveRequireCandidates('js/common/smProvider.js', '../configLoader.js');
        assert.deepEqual(bases, ['js/configLoader.js']);
    });
});

suite('require gate: the self-test verdict', function () {

    test('a complete pack resolves clean (the 091304 zip shape, WITH the file)', function () {
        // Verified against the real agents-rel-20261009-091304 artifact: the
        // shipped zip DOES carry js/common/reviewVerdicts.js — a complete,
        // self-consistent pack must pass the gate.
        var files = [
            { path: 'js/smAgent.js', source: "var m = require('./common/reviewVerdicts.js');" },
            { path: 'js/common/smProvider.js', source: "var m = require('./reviewVerdicts.js');" },
            { path: 'js/common/reviewVerdicts.js', source: 'var x = 1;' },
        ];
        assert.deepEqual(gate().unresolvedRequires(files), []);
    });

    test('L2 red-team: the mixed 091304-content shape FAILS — requiring code without the file', function () {
        // What the fa runners executed at 09:36Z: post-gh-807 smProvider.js
        // (lazy require of ./reviewVerdicts.js) over an installed 0.1.36 tree
        // from 075526 — 16 js files, js/common/reviewVerdicts.js absent.
        var files = [
            { path: 'js/smAgent.js', source: "var m = require('./common/reviewVerdicts.js');" },
            { path: 'js/common/smProvider.js', source: [
                'var mod = null;',
                'function f() {',
                "    mod = require('./reviewVerdicts.js');",
                '}',
            ].join('\n') },
            { path: 'js/common/scm.js', source: 'var x = 1;' },
        ];
        var unresolved = gate().unresolvedRequires(files);
        assert.equal(unresolved.length, 2,
            'the gate must fail the release for this pack (gh-812 AC3: exit != 0)');
        var targets = unresolved.map(function (u) { return u.target; }).sort();
        assert.deepEqual(targets, ['js/common/reviewVerdicts.js', 'js/common/reviewVerdicts.js'].sort());
    });

    test('the 075526 shape (no require, no file) passes — nothing to resolve', function () {
        var files = [
            { path: 'js/smAgent.js', source: 'var x = 1;' },
            { path: 'js/common/smProvider.js', source: 'var y = 2;' },
        ];
        assert.deepEqual(gate().unresolvedRequires(files), []);
    });

    test('a worker-source require resolves via the js/ module root base', function () {
        // Real githubSource.js shape: the worker string only makes sense
        // root-relative — the gate must accept it when js/common/smProvider.js
        // is in the zip (a pure file-relative gate would false-positive it).
        var files = [
            { path: 'js/sm/sources/githubSource.js', source: "var W = ['function(args) {', \"    var mod = require('./common/smProvider.js');\", '}'].join('\\n');" },
            { path: 'js/common/smProvider.js', source: 'var x = 1;' },
        ];
        assert.deepEqual(gate().unresolvedRequires(files), []);
    });

    test('a worker-source require FAILS when the root-relative target is abse…

/**
 * Unit tests: the pack-release version guard (gh-812).
 *
 * Guards the gh-812 root cause (live 2026-10-09): the release builder
 * derived pack versions from versions.json on main — a ledger whose push
 * back to main is best-effort (a rejected direct push only warns). The
 * ledger never landed, so EIGHT consecutive releases (20261008-095538 →
