431	function main() {
432	  const versions = readVersions();
433	  const affected = computeAffectedSet();
434	  const setupOnly = setupTouched();
435	  if (affected.length === 0 && !setupOnly) {
436	    console.log('No affected agents and no setup change — nothing to release.');
437	    // dist/ may not exist yet (the build below is skipped) — create it or
438	    // the marker write throws ENOENT and the job fails (live: release run
439	    // 2026-09-30T09:11 on a push whose BASE diff was empty).
440	    mkdirSync(OUT_DIR, { recursive: true });
441	    writeFileSync(join(OUT_DIR, '.no-release'), 'no affected agents\n');
442	    return;
443	  }
444	  console.log(`Affected agents (${affected.length}): ${affected.join(', ') || '<none — factory-setup-only>'}`);
445	  mkdirSync(OUT_DIR, { recursive: true });
446	
447	  // Bump ONLY the affected agents (incremental versioning), but BUILD and
448	  // catalog EVERY agent: each release must be a self-contained snapshot.
449	  // The registry resolver resolves `<agent>@latest` against the NEWEST
450	  // release's catalog.json — an affected-only catalog hides every agent
451	  // that was not touched by this release, and their packs are absent from
452	  // the release assets too, so `@latest` AND `@<version>` both fail
453	  // (live: epam/dmtools-dart machine-merge, 2026-09-29 —
454	  // "Agent 'machine_merge' not found in registry catalog .../catalog.json"
455	  // because the 19:07 release bumped only sm_github).
456	  const agents = allAgents();
457	  const catalog = {};
458	  const ledgerBefore = { ...versions };
459	  for (const agent of agents) {
460	    const ledgerVersion = versions[agent] || '0.1.0';
461	    const shippedVersion = shippedCatalog()[agent] || null;
462	    const isAffected = affected.includes(agent);
463	    // gh-812 V1/V2: the base is what the previous release SHIPPED for this
464	    // agent (append-only, cannot be rewritten by a failed ledger push); the
465	    // versions.json ledger is only the fallback. Bumping from a stale ledger
466	    // re-shipped a live version with new content — the gh-812 collision.
467	    let next = resolveCandidateVersion(resolveBaseVersion(ledgerVersion, shippedVersion), BUMP, isAffected);
468	    console.log(`\n=== ${agent}: ledger ${ledgerVersion}, shipped ${shippedVersion || '<none>'}${next !== ledgerVersion ? ` -> ${next}` : ' (unchanged)'} ===`);
469	    if (!DRY_RUN) {
470	      const built = buildPackRelease(agent, next, isAffected, shippedVersion);
471	      next = built.version;
472	      versions[agent] = next;
473	    }
474	    catalog[agent] = next;
475	  }
476	
477	  if (!DRY_RUN) {
478	    // Write the ledger whenever any final version diverges from what it
479	    // said — affected bumps, gh-812 forced re-versionings, and the
480	    // reconciliation of a ledger that lagged the shipped catalog.
481	    const ledgerChanged = agents.some((a) => versions[a] !== (ledgerBefore[a] || '0.1.0'));
482	    if (ledgerChanged) {
483	      writeFileSync(VERSIONS_FILE, JSON.stringify(versions, null, 2) + '\n');
484	    }
485	    // The factory-setup asset rides EVERY release (self-contained snapshot,
486	    // same rule as the agent packs) — the factory downloads it by tag, so a
487	    // stale asset on a fresh tag would silently pin old workflow glue.
488	    buildFactorySetup();
489	    writeFileSync(join(OUT_DIR, 'catalog.json'), JSON.stringify(catalog, null, 2) + '\n');
490	    console.log(`\nWrote ${OUT_DIR}/catalog.json (${agents.length} agents, ${affected.length} bumped, factory-setup shipped)`);
491	  }
492	}
493	
