247	      { stdio: ['ignore', 'ignore', 'ignore'] },
248	    );
249	    const manifestJson = execSync(
250	      `unzip -p ${JSON.stringify(join(SHIPPED_DIR, `${agent}-${version}.zip`))} manifest.json`,
251	      { encoding: 'utf8' },
252	    );
253	    SHIPPED_ZIP_MANIFESTS[key] = manifestJson;
254	  } catch (e) {
255	    console.warn(`::warning::could not fetch shipped ${key}.zip for the payload comparison (${String(e.message).split('\n')[0]}) — shipping at the candidate version`);
256	    SHIPPED_ZIP_MANIFESTS[key] = null;
