463	    // gh-812 V1/V2: the base is what the previous release SHIPPED for this
464	    // agent (append-only, cannot be rewritten by a failed ledger push); the
465	    // versions.json ledger is only the fallback. Bumping from a stale ledger
466	    // re-shipped a live version with new content — the gh-812 collision.
467	    let next = resolveCandidateVersion(resolveBaseVersion(ledgerVersion, shippedVersion), BUMP, isAffected);
