469	    if (!DRY_RUN) {
470	      const built = buildPackRelease(agent, next, isAffected, shippedVersion);
471	      next = built.version;
472	      versions[agent] = next;
473	    }
474	    catalog[agent] = next;
475	  }
476	
477	  if (!DRY_RUN) {
478	    // Write the ledger whenever any final version diverges from what it
479	    // said — affected bumps, gh-812 forced re-versionings, and the
480	    // reconciliation of a ledger that lagged the shipped catalog.
481	    const ledgerChanged = agents.some((a) => versions[a] !== (ledgerBefore[a] || '0.1.0'));
