393	 * Builds ONE agent pack release-ready: compile → launch-surface augment →
394	 * gh-812 payload-drift re-version (an unchanged version must never re-ship
395	 * changed content) → require sanity gate → manifest validation. The guarded
396	 * chain stays literal and in order (build → augment → validate — see
397	 * test_packLaunchContract); [next] is the version to build at and is
398	 * advanced when the drift check forces a re-version. Returns the shipped
399	 * { zipPath, version }.
400	 */
401	function buildPackRelease(agent, next, isAffected, shippedVersion) {
402	  // ALWAYS build every agent zip — a factory-setup-only release is a
403	  // RELEASE too and must stay a self-contained snapshot. Skipping the
404	  // build on an empty affected set shipped a catalog that advertised
405	  // packs the release never carried, and the registry resolver 404'd
406	  // on `@latest` (live: fa SM tick 2026-10-03T08:49, sm_github-0.1.18
407	  // in catalog, zip absent from agents-rel-20261003-084425).
408	  const zip = buildPack(agent, next);
409	  augmentLaunchSurface(agent, zip);
410	  // gh-812 V3: a rebuilt-but-unbumped agent whose payload differs from the
411	  // zip its version already shipped is the exact collision class that put
412	  // two different sm_github-0.1.36.zip files into 075526 and 091304 —
413	  // re-version one patch up instead of republishing under the same name.
414	  if (!isAffected && shippedVersion === next &&
415	      fingerprintsDiffer(shippedZipManifest(agent, shippedVersion), zipManifestText(zip))) {
416	    next = resolveShipVersion(next, true);
417	    console.log(`  payload differs from shipped ${shippedVersion} — re-versioning to ${next} (gh-812: never republish changed content under a shipped version)`);
418	    const rezipped = buildPack(agent, next);
419	    augmentLaunchSurface(agent, rezipped);
420	    assertZipRequires(rezipped); // gh-812 AC1/AC3 — throws before ledger commit + publish
421	    const recount = validatePack(rezipped);
422	    console.log(`validated ${basename(rezipped)} (${recount} files)`);
423	    return { zipPath: rezipped, version: next };
424	  }
425	  assertZipRequires(zip); // gh-812 AC1/AC3 — throws before ledger commit + publish
426	  const count = validatePack(zip);
427	  console.log(`validated ${basename(zip)} (${count} files)`);
428	  return { zipPath: zip, version: next };
429	}
